    ["I once laughed so hard, I milked all over the floor."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["I owe you one."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["I require aid!"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
