    ["I thank you."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["I think that guys just use the Emerald Dream as an excuse to avoid calling me back."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["I think that last vendor short changed me.  Oh, that was a bad one."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["I want a man with soft hands.  Preferably four of them."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
