    ["If %s joins your group, you will be removed from the following queues:"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If I said you had a good body, would you hold it against me?"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If I wasn't purple, you'd see I was blushing."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If a player joins the party, quests will be re-synced. Are you sure?"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If cannibalism be wrong, I don't want to be right."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If checked, Clean Up Bags will move items to your rightmost bags."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If checked, all raid members will have the permissions of a Raid Assistant."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["If checked, invitees whom respond to this event will have their status approved automatically; otherwise, you will have to approve them manually."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
