    ["In order to link this guild to Discord you need to authenticate with your character"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["In order to use this option accessibility needs to be enabled. Please check the option \\\"Enable access for assistive devices\\\" in the Universal Access System Preferences panel. Would you like to open the System Preferences now?"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["In order to use this option, you must grant access to %s in Security & Privacy preferences, located in System Preferences. Would you like to open System Preferences now?"] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
    ["In order to use voice chat, you must grant \"Microphone\" permission to %s in Security & Privacy preferences, located in System Preferences."] = { ["source"] = "client_global_strings", ["tier"] = "validated_legacy" },
